package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamMeditationBank {
  private const val T = "කර්මය, පුනර්භවය හා චිත්ත සංවර්ධනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("සමථ භාවනාවෙන් ප්‍රධාන වශයෙන් අපේක්ෂා කරන්නේ කුමක්ද?", "චිත්ත ඒකාග්‍රතාව හා නීවරණ යටපත් කිරීම", "පංචස්කන්ධය නිත්‍ය ලෙස දැකීම", "කායික ශක්තිය වැඩි කිරීම", "මන්ත්‍ර බලය ලබා ගැනීම", "සමථ භාවනාවෙන් සිත සමාහිත වී ධ්‍යාන උපදී."),
    q("විදර්ශනා භාවනාවෙන් ප්‍රධාන වශයෙන් සාක්ෂාත් කරන්නේ කුමක්ද?", "ත්‍රිලක්ෂණය අවබෝධ කර කෙලෙස් නැසීම", "අෂ්ට සමාපත්ති ලබා ගැනීම පමණි", "දෙව්ලොව උපත ලැබීම පමණි", "ඍද්ධි ප්‍රාතිහාර්ය පෑම පමණි", "විදර්ශනාව ප්‍රඥාව වඩා නිවනට පමුණුවයි."),
    q("සමථ භාවනා කමටහන් කොපමණ සංඛ්‍යාවක් බෞද්ධ ග්‍රන්ථවල දැක්වේද?", "සතළිසකි", "තිස්හතකි", "සොළොසකි", "දසයකි", "කසිණ 10, අසුභ 10, අනුස්සති 10 ආදී ලෙස සමථ කමටහන් 40 කි."),
    q("පඨවි, ආපෝ, තේජෝ, වායෝ ආදී වශයෙන් සමථ භාවනාවේ දැක්වෙන කසිණ ගණන කීයද?", "දසයකි", "අටකි", "සතරකි", "දොළසකි", "සතර මහා භූත, වර්ණ 4, ආලෝක හා ආකාස ලෙස කසිණ 10 කි."),
    q("බුද්ධානුස්සති, ධම්මානුස්සති, සංඝානුස්සති යන භාවනා අයත් වන්නේ කුමන කමටහන් කොටසටද?", "දස අනුස්සති", "දස අසුභ", "දස කසිණ", "සතර බ්‍රහ්ම විහරණ", "බුදු, දහම්, සඟ ගුණ සිහි කිරීම අනුස්සති භාවනාවට අයත් වේ."),
    q("මෛත්‍රී, කරුණා, මුදිතා, උපේක්ෂා යන ධර්මතා හතර හැඳින්වෙන්නේ කුමන නමකින්ද?", "සතර බ්‍රහ්ම විහරණ", "සතර සංග්‍රහ වස්තු", "සතර සතිපට්ඨාන", "සතර ඉර්දිපාද", "මේවා සතර අප්‍රමාණ හෙවත් බ්‍රහ්ම විහරණ නම් වේ."),
    q("මෛත්‍රී භාවනාව වැඩීමෙන් පහළ වන ප්‍රධාන ප්‍රතිඵලයක් නොවන්නේ කුමක්ද?", "සතුරන් කෙරෙහි කෝපය වැඩි වීම", "සුවසේ නින්ද යෑම", "සුවසේ අවදි වීම", "දෙවියන්ට ප්‍රිය වීම", "මෙත්තානිසංස සූත්‍රයේ මෛත්‍රී භාවනාවේ ආනිසංස 11 ක් දැක්වේ."),
    q("අන් අයගේ දුකේදී සිතේ උණුසුම් බවක් ඇතිවී ඉන් මුදවා ගැනීමට කැමති වීම කුමන බ්‍රහ්ම විහරණයද?", "කරුණාව", "මුදිතාව", "උපේක්ෂාව", "මෛත්‍රිය", "දුකට පත් සත්වයන් කෙරෙහි හටගන්නා සානුකම්පිත සිත කරුණාවයි."),
    q("අනුන්ගේ දියුණුව හා සතුට දැක ඊර්ෂ්‍යාවෙන් තොරව සතුටු වීමේ ගුණය කුමක්ද?", "මුදිතාව", "කරුණාව", "උපේක්ෂාව", "ද්වේෂය", "ඊර්ෂ්‍යාව දුරු කරන උසස් සමාජීය ගුණය මුදිතාවයි."),
    q("දුක සැප දෙකේදී හා සතුරු මිතුරු දෙපිරිස කෙරෙහි සම සිතින් කටයුතු කිරීම කුමක්ද?", "උපේක්ෂාව", "මුදිතාව", "කරුණාව", "විචිකිච්ඡාව", "මධ්‍යස්ථ ස්වභාවය පවත්වා ගැනීම උපේක්ෂා බ්‍රහ්ම විහරණයයි."),
    q("චිත්ත සමාධිය ඇතිවීමට බාධා කරන 'පංච නීවරණ' අතර කාම වස්තූන් කෙරෙහි ඇතිවන දැඩි ආශාව කුමක්ද?", "කාමච්ඡන්දය", "ව්‍යාපාදය", "ථීනමිද්ධය", "උද්ධච්ච කුක්කුච්චය", "කාමච්ඡන්දය පළමු නීවරණය ලෙස සිත ආවරණය කරයි."),
    q("සිතෙහි ඇතිවන අලසකම හා නිදිමත ස්වභාවය හඳුන්වන නීවරණය කුමක්ද?", "ථීනමිද්ධය", "ව්‍යාපාදය", "විචිකිච්ඡාව", "කාමච්ඡන්දය", "වීර්යය හීන කරන මැලිකම ථීනමිද්ධ නීවරණයයි."),
    q("සිතේ නොසන්සුන් බව හා කළ නොකළ දේ ගැන පසුතැවීම යන නීවරණය කුමක්ද?", "උද්ධච්ච කුක්කුච්චය", "ථීනමිද්ධය", "ව්‍යාපාදය", "කාමච්ඡන්දය", "උද්ධච්චය යනු සිතේ විසිරීම වන අතර කුක්කුච්චය යනු පසුතැවීමයි."),
    q("තෙරුවන් හා කර්මඵල පිළිබඳව සිතේ ඇතිවන සැකය හඳුන්වන්නේ කුමන නීවරණයෙන්ද?", "විචිකිච්ඡාව", "ව්‍යාපාදය", "කාමච්ඡන්දය", "ථීනමිද්ධය", "සැකය නිසා භාවනා මාර්ගයේ ඉදිරියට යාම අඩාල වේ."),
    q("භාවනාවේදී කාමච්ඡන්ද නීවරණය උපමා කර ඇත්තේ කුමකටද?", "වර්ණවත් කළ දිය බඳුනකට", "උණු වන ජල බඳුනකට", "සෙවෙලින් වැසුණු ජලයට", "සුළඟින් කැළඹුණු ජලයට", "රන් ආභරණ ආදියෙන් මනස මුළා කරන වර්ණ ජලයට කාමච්ඡන්දය උපමා වේ."),
    q("ව්‍යාපාද නීවරණය උපමා කර දැක්වෙන්නේ කුමන ජල බඳුනටද?", "ගින්නෙන් පැසෙන ජල බඳුනට", "අඳුරේ තැබූ ජල බඳුනට", "පාසි බැඳුණු ජල බඳුනට", "සායම් මිශ්‍ර ජල බඳුනට", "ද්වේෂයෙන් සිත දැවෙන බව පැසෙන ජලයෙන් පෙන්වයි."),
    q("ථීනමිද්ධ නීවරණය බෞද්ධ සූත්‍රවල උපමා කර ඇත්තේ කුමකටද?", "පාසි හා සෙවෙලින් වැසුණු ජල බඳුනට", "සුළඟින් කැළඹුණු ජලයට", "පැසෙන උණු ජලයට", "කළුවරේ තැබූ මඩ ජලයට", "සෙවෙල් නිසා මුහුණ නොපෙනෙන්නා සේ ථීනමිද්ධය නුවණ වසයි."),
    q("උද්ධච්ච කුක්කුච්ච නීවරණය උපමා කර ඇති ජල ස්වභාවය කුමක්ද?", "සුළඟින් කැළඹී රැළි නගන ජලය", "සෙවෙල් බැඳුණු ජලය", "වර්ණ මිශ්‍ර ජලය", "නටන උණු ජලය", "සිතේ නොසන්සුන් බව රැළි නගන ජලයෙන් උපමා කෙරේ."),
    q("විචිකිච්ඡා නීවරණය උපමා කර ඇත්තේ කුමන ජල බඳුනකටද?", "අඳුරේ තැබූ කැළඹුණු මඩ ජලයට", "පිරිසිදු නිල් ජලයට", "පැසෙන ජලයට", "සුළඟින් සැලෙන ජලයට", "සැකය ඇති විට සත්‍යය නොපෙනෙන බව මින් පැහැදිලි වේ."),
    q("කායානුපස්සනා, වේදනානුපස්සනා, චිත්තානුපස්සනා, ධම්මානුපස්සනා යනු කුමක්ද?", "සතර සතිපට්ඨානය", "සතර ඍද්ධිපාද", "සතර සම්‍යක්ප්‍රධාන", "සතර අප්‍රමාණ", "නිවන් දැකීමේ එකම මග ලෙස සතිපට්ඨාන සූත්‍රයේ මේ හතර දැක්වේ."),
    q("සතිපට්ඨාන භාවනාවේදී හුස්ම ඉහළ පහළ ගැනීම පිළිබඳ සිහියෙන් සිටීම කුමන භාවනාවද?", "ආනාපානසති භාවනාව", "අසුභ භාවනාව", "මරණානුස්සති භාවනාව", "කසිණ භාවනාව", "ආශ්වාස ප්‍රශ්වාස අරමුණු කර සිත සමාහිත කිරීම ආනාපානසතියයි."),
    q("ශරීරයේ කෙස්, ලොම්, නිය, දත්, සම ආදී කොටස් දෙතිස ගැන සිහි කිරීම කුමන භාවනාවද?", "දෙතිස් කුණුප භාවනාව", "ධාතු මනසිකාරය", "ඉරියාපථ පබ්බය", "සම්පජඤ්ඤ පබ්බය", "කයෙහි ඇති නිසරු බව වටහා ගැනීමට මෙම කායගතාසතිය උපකාරී වේ."),
    q("නිදා ගැනීම, අවදි වීම, ඉඳීම, සිටීම යන ඉරියව් සතර ගැන සිහියෙන් සිටීම කුමක්ද?", "ඉරියාපථ පබ්බය", "ආනාපාන පබ්බය", "නවසීවථික පබ්බය", "පටික්කූල මනසිකාරය", "සෑම ඉරියව්වකදීම සිහිය පවත්වා ගැනීම කායානුපස්සනාවට අයත් වේ."),
    q("සිතේ පහළ වන සරාගී හෝ වීතරාගී ආදී සිත්වල ස්වභාවය නිරීක්ෂණය කිරීම කුමක්ද?", "චිත්තානුපස්සනාව", "වේදනානුපස්සනාව", "කායානුපස්සනාව", "ධම්මානුපස්සනාව", "මනසේ ඇතිවන විවිධ සිත් අනිත්‍ය ලෙස බැලීම චිත්තානුපස්සනාවයි."),
    q("සප්ත බොජ්ඣංග, ආර්ය සත්‍යය, නීවරණ ආදිය මෙනෙහි කර බැලීම අයත් වන්නේ කුමන අනුපස්සනාවටද?", "ධම්මානුපස්සනාවට", "කායානුපස්සනාවට", "වේදනානුපස්සනාවට", "චිත්තානුපස්සනාවට", "ධර්ම කොටස් පිළිබඳ විමසා බැලීම ධම්මානුපස්සනාවට අයත් වේ."),
    q("සප්ත බොජ්ඣංග ධර්ම අතර මුලින්ම දැක්වෙන ධර්ම අංගය කුමක්ද?", "සති සම්බොජ්ඣංගය", "විරිය සම්බොජ්ඣංගය", "පස්සද්ධි සම්බොජ්ඣංගය", "උපේක්ඛා සම්බොජ්ඣංගය", "සති, ධම්මවිචය, විරිය, පීති, පස්සද්ධි, සමාධි, උපේක්ඛා සප්ත බොජ්ඣංග වේ."),
    q("කයේ හා සිතේ සැහැල්ලු බව හා සංසිඳීම ඇති කරන බොජ්ඣංග ධර්මය කුමක්ද?", "පස්සද්ධි සම්බොජ්ඣංගය", "විරිය සම්බොජ්ඣංගය", "ධම්මවිචය සම්බොජ්ඣංගය", "සති සම්බොජ්ඣංගය", "ප්‍රීතියෙන් පසු කය සිත සන්සුන් වීම පස්සද්ධියයි."),
    q("ධ්‍යාන උපදවා ගැනීමේදී ප්‍රථම ධ්‍යානයේ පවතින ධ්‍යානාංග ගණන කීයද?", "පහකි", "තුනකි", "දෙකකි", "සතරකි", "විතක්ක, විචාර, පීති, සුඛ, ඒකග්ගතා යන අංග පහ ප්‍රථම ධ්‍යානයේ ඇත."),
    q("ප්‍රථම ධ්‍යානයෙන් දෙවන ධ්‍යානයට පත්වීමේදී ප්‍රහාණය වන ධ්‍යානාංග දෙක මොනවාද?", "විතක්ක හා විචාර", "පීති හා සුඛ", "සුඛ හා උපේක්ඛා", "ඒකග්ගතා හා සති", "දෙවන ධ්‍යානයේදී අවිතක්ක අවිචාර පීති සුඛ ඒකග්ගතා පවතී."),
    q("සතරවන රූපාවචර ධ්‍යානයේ ඉතිරි වන ධ්‍යානාංග දෙක මොනවාද?", "උපේක්ඛා හා ඒකග්ගතා", "විතක්ක හා විචාර", "පීති හා සුඛ", "සති හා කරුණා", "සැප දුක් දෙකම ප්‍රහාණය කර පිරිසිදු උපේක්ෂාව හා ඒකග්ගතාව පවතී."),
    q("අරූපාවචර ධ්‍යාන (සමාපත්ති) කොපමණ සංඛ්‍යාවක් ඇත්ද?", "හතරකි", "පහකි", "තුනකි", "අටකි", "ආකාසානඤ්චායතන, විඤ්ඤාණඤ්චායතන, ආකිඤ්චඤ්ඤායතන, නේවසඤ්ඤානාසඤ්ඤායතන සතරකි."),
    q("සියලු ධ්‍යානවලට අමතරව රහතුන් හා අනාගාමීන් සමවදින උසස් සමාපත්තිය කුමක්ද?", "නිරෝධ සමාපත්තිය", "ප්‍රථම ධ්‍යානය", "විදර්ශනා සමාපත්තිය", "ආකාසානඤ්චායතනය", "සිත හා චෛතසික තාවකාලිකව නිරුද්ධ කරන සඤ්ඤාවේදයිත නිරෝධයයි."),
    q("කර්මය යන්නෙහි බෞද්ධ විග්‍රහය අනුව එහි ප්‍රධාන ස්වභාවය කුමක්ද?", "චේතනාව මුල් වී කරන ක්‍රියාව", "අහඹු ලෙස සිදුවන දේ", "දෙවියන්ගේ කැමැත්ත", "නැකැත් අනුව සිදුවන දේ", "'චේතනාහං භික්ඛවේ කම්මං වදාමි' ලෙස චේතනාව කර්මය බව වදාළහ."),
    q("ද්වාර වශයෙන් කර්මය බෙදා ඇති ආකාර තුන මොනවාද?", "කාය, වචී, මනෝ කර්ම", "දිට්ඨ, සුත, මුත කර්ම", "කාම, රූප, අරූප කර්ම", "අතීත, අනාගත, වර්තමාන කර්ම", "සිත, කය, වචනය යන තුන්දොරින් කර්ම රැස් වේ."),
    q("විපාක දෙන කාලය අනුව කර්ම බෙදෙන ප්‍රධාන කොටස් හතරෙන් මේ ජීවිතයේම විපාක දෙන කර්මය කුමක්ද?", "දිට්ඨධම්මවේදනීය කර්මය", "උපපජ්ජවේදනීය කර්මය", "අපරාපරියවේදනීය කර්මය", "අහෝසි කර්මය", "පළමු ජවන් සිතෙන් සිදුවී මේ ආත්මයේදීම විපාක දෙන කර්මය මෙයයි."),
    q("ඊළඟ ආත්මභාවයේදී විපාක දීමට නියමිත කර්මය හඳුන්වන්නේ කුමන නමින්ද?", "උපපජ්ජවේදනීය කර්මය", "දිට්ඨධම්මවේදනීය කර්මය", "අහෝසි කර්මය", "ගරුක කර්මය", "මරණින් මතු දෙවන භවයේදී විපාක දෙන කර්මය උපපජ්ජවේදනීය වේ."),
    q("පිරිනිවන් පානා තෙක් සසරේ කවර හෝ භවයක විපාක දෙන කර්මය කුමක්ද?", "අපරාපරියවේදනීය කර්මය", "දිට්ඨධම්මවේදනීය කර්මය", "උපපජ්ජවේදනීය කර්මය", "අහෝසි කර්මය", "තුන්වන භවයේ සිට නිවන් දකින තුරුම ඉඩ ලැබෙන විට විපාක දෙයි."),
    q("විපාක දීමට කාලය ඉක්ම යෑමෙන් හෝ රහත් වීමෙන් නිෂ්ඵල වන කර්මය කුමක්ද?", "අහෝසි කර්මය", "ගරුක කර්මය", "ආසන්න කර්මය", "කටත්තා කර්මය", "විපාක දීමට අවස්ථාව නොලැබී අවසන් වූ කර්මය අහෝසි කර්මයයි."),
    q("විපාක දීමේ ශක්තිය හෙවත් කෘත්‍ය අනුව කර්ම බෙදෙන කොටස් හතරෙන් එකක් වන 'ජනක කර්මය' යනු කුමක්ද?", "ප්‍රතිසන්ධිය හා විපාක උපදවන කර්මය", "කර්මයක විපාකය නවතාලන කර්මය", "වෙනත් කර්මයකට රුකුල් දෙන කර්මය", "කර්ම විපාකය විනාශ කරන කර්මය", "අලුත් භවයක උපත ලබා දෙන කර්මය ජනක කර්මයයි."),
    q("උපත ලබා දුන් ජනක කර්මයට අනුව ජීවිතය පවත්වා ගෙන යාමට උපකාරී වන කර්මය කුමක්ද?", "උපත්ථම්භක කර්මය", "උපපීළක කර්මය", "උපඝාතක කර්මය", "ආචිණ්ණක කර්මය", "පවතින සැප හෝ දුක් විපාක තවදුරටත් පෝෂණය කරමින් රුකුල් දෙයි."),
    q("කලින් කළ කර්මයක විපාක දීමේ ශක්තිය අඩු කර පීඩා කරන කර්මය කුමක්ද?", "උපපීළක කර්මය", "ජනක කර්මය", "උපත්ථම්භක කර්මය", "ගරුක කර්මය", "සුබ විපාක අඩු කිරීමට හෝ දුක් විපාක සමනය කිරීමට උපපීළක කර්මය බලපායි."),
    q("වෙනත් කර්මයක බලය සම්පූර්ණයෙන්ම සිඳ දමා තමාගේ විපාකය මතු කරන කර්මය කුමක්ද?", "උපඝාතක කර්මය", "උපත්ථම්භක කර්මය", "කටත්තා කර්මය", "ආසන්න කර්මය", "දුර්වල කර්ම විපාකය නසා දමන බලවත් කර්මය උපඝාතක වේ."),
    q("විපාක දීමේ පිළිවෙළ අනුව මුලින්ම විපාක දෙන අනිවාර්ය කර්මය කුමක්ද?", "ගරුක කර්මය", "ආසන්න කර්මය", "ආචිණ්ණක කර්මය", "කටත්තා කර්මය", "පංච ආනන්තරිය පාප කර්ම හා ධ්‍යාන කුසල කර්ම ගරුක කර්ම වේ."),
    q("නිතර නිතර පුරුදු පුහුණු කරන ලද කුසලාකුසල ක්‍රියා අයත් වන්නේ කුමන කර්ම කොටසටද?", "ආචිණ්ණක (බහුල) කර්මය", "ආසන්න කර්මය", "කටත්තා කර්මය", "ගරුක කර්මය", "දිනපතා මව්පිය උපස්ථානය හෝ සතුන් මැරීම ආදිය ආචිණ්ණක කර්ම වේ."),
    q("මරණාසන්න මොහොතේදී සිතට නැගෙන ක්‍රියාවන් විපාක දීම හඳුන්වන්නේ කුමන නමින්ද?", "ආසන්න කර්මය", "ගරුක කර්මය", "කටත්තා කර්මය", "අහෝසි කර්මය", "මරණ මොහොතේ සිහිපත් වන කුසල හෝ අකුසල කර්මය ප්‍රතිසන්ධියට බලපායි."),
    q("පෙර ගරුක, ආසන්න, ආචිණ්ණක කර්ම නොමැති විට විපාක දීමට ඉතිරිව ඇති සාමාන්‍ය කර්මය කුමක්ද?", "කටත්තා කර්මය", "ජනක කර්මය", "දිට්ඨධම්මවේදනීය කර්මය", "ගරුක කර්මය", "සිතාමතා දැඩිව නොකළත් රැස් වූ අවශේෂ කර්මය කටත්තා නම් වේ."),
    q("පංච ආනන්තරිය කර්ම පහට අයත් නොවන්නේ පහත සඳහන් කුමක්ද?", "සොරකම් කිරීම", "මව මැරීම", "පියා මැරීම", "සංඝභේදය කිරීම", "මව, පියා, රහතුන් මැරීම, බුදු සිරුරේ ලේ සෙලවීම, සංඝභේදය පංච ආනන්තරිය කර්ම වේ."),
    q("අභිධර්මයට අනුව කුසල් හා අකුසල් සිත් හටගැනීමට හේතු වන ප්‍රධාන සංස්කාර ක්‍රියාවලිය කුමක්ද?", "ජවන් සිත් පහළ වීම", "භවාංග සිත පමණක්", "පංචද්වාරාවජ්ජනය", "හසිතුප්පාද සිත", "ජවන් චිත්ත වීථි මගින් කුසලාකුසල කර්ම රැස් කෙරේ."),
    q("සිත දියුණු කිරීමට බාධා කරන චිත්ත උපක්ලේශ නැති කිරීමට බුදුරදුන් දෙසූ 'විතක්ක සණ්ඨාන සූත්‍රයේ' පියවර කීයක් වේද?", "පහකි", "තුනකි", "හතකි", "දසයකි", "අරමුණ මාරු කිරීමේ සිට තදින් සිත පාලනය දක්වා උපක්‍රම 5 ක් දක්වා ඇත."),
    q("සියලු භාවනා ක්‍රමවල මූලික පරමාර්ථය විය යුත්තේ කුමක්ද?", "ලෝභ, ද්වේෂ, මෝහ තුනී කර සිත පිරිසිදු කිරීම", "අනුන්ගේ සිත් කියවා පෙන්වීම", "සමාජයේ ජනප්‍රිය වීම", "ධනවත් වීම", "සිතේ කෙලෙස් ක්ෂය කිරීම සැබෑ භාවනාවේ අරමුණයි."),
    q("පුද්ගලයෙකු මියගිය පසු පෙර භවයේ ස්කන්ධ නොගොස් නව භවයක් හටගන්නා බව පෙන්වන උපමාව කුමක්ද?", "පහනකින් තව පහනක් දැල්වීම", "වළඳක් බිඳී යාම", "ගසක් කපා දැමීම", "ජලය වාෂ්ප වීම", "මිලින්ද ප්‍රශ්නයේදී හේතුඵල සම්බන්ධයෙන් පුනර්භවය මෙසේ උපමා කර ඇත."),
    q("කර්ම විපාක සෑම විටම පුද්ගලයෙකුට අනිවාර්ය නියතිවාදයක් නොවන බව පෙන්වන දේශනාව කුමක්ද?", "ලෝණඵල සූත්‍රය", "ආලවක සූත්‍රය", "රතන සූත්‍රය", "සිඟාලෝවාද සූත්‍රය", "ලුණු කැටයක් කෝප්පයකට හා ගඟකට දැමීමේ උපමාව ලෝණඵල සූත්‍රයේ දැක්වේ."),
    q("කළ කුඩා අකුසලයක් මහා කුසල ශක්තිය නිසා බලපෑම අඩු වන බව ලෝණඵල සූත්‍රයේ පෙන්වූ උපමාව කුමක්ද?", "ගංගා නදියට ලුණු කැටයක් දැමීම", "සාගරයට ගලක් දැමීම", "ගින්නට තෙල් දැමීම", "මඩට මලක් දැමීම", "සීල සමාධි ප්‍රඥා වඩන කල කුඩා පව් විපාක තුනී වන බව පෙන්වයි."),
    q("සියල්ල පෙර කර්මය නිසාම සිදුවේ යැයි පිළිගන්නා වැරදි දෘෂ්ටිය කුමක්ද?", "පුබ්බේකතහේතුවාදය", "ඉස්සරනිම්මාණවාදය", "අහේතුඅප්පච්චයවාදය", "පටිච්චසමුප්පාදය", "දේවදූත සූත්‍ර හා තිත්ථායතන සූත්‍රවල බුදුරදුන් මෙම අන්තවාදී මත බැහැර කළහ."),
    q("සියල්ල සර්වබලධාරී දෙවියෙකුගේ කැමැත්තෙන් සිදුවේ යැයි ගන්නා මතය කුමක්ද?", "ඉස්සරනිම්මාණවාදය", "පුබ්බේකතහේතුවාදය", "අහේතුඅප්පච්චයවාදය", "කර්මවාදය", "මිනිසාගේ උත්සාහය හා වීර්යය නොසලකා හරින මිථ්‍යා දෘෂ්ටියකි."),
    q("කිසිදු හේතුවක් හෝ ප්‍රත්‍යයක් නොමැතිව සියල්ල අහම්බෙන් සිදුවේ යන මතය කුමක්ද?", "අහේතුඅප්පච්චයවාදය", "පුබ්බේකතහේතුවාදය", "ඉස්සරනිම්මාණවාදය", "නියතිවාදය", "බුදුදහම හේතුඵලවාදය මිස අහේතුවාදය නොවේ."),
    q("මනුෂ්‍යයාගේ සෑම ක්‍රියාවකටම හේතු නියාම ධර්ම පහක් බලපාන බව ඉගැන්වෙන්නේ කුමන ඉගැන්වීමෙන්ද?", "පංච නියාම ධර්ම", "පංච උපාදානස්කන්ධ", "පංච ශීලය", "පංච බල", "උතු, බීජ, කම්ම, ධම්ම, චිත්ත යනු පංච නියාම ධර්මයි."),
    q("ඍතු හා කාලගුණික විපර්යාස සිදුවීම අයත් වන්නේ කුමන නියාම ධර්මයටද?", "උතු නියාමය", "බීජ නියාමය", "කම්ම නියාමය", "චිත්ත නියාමය", "වර්ෂාව, ශීතල, උණුසුම ආදිය උතු නියාමයෙන් ක්‍රියාත්මක වේ."),
    q("අඹ ඇටයකින් අඹ පැළයක්ම හටගැනීම හා ප්‍රවේණි ලක්ෂණ උරුම වීම කුමන නියාමයද?", "බීජ නියාමය", "උතු නියාමය", "ධම්ම නියාමය", "කම්ම නියාමය", "ශාක හා සත්ව ප්‍රවේණි ස්වභාවය බීජ නියාමයයි."),
    q("සිතුවිලි පරම්පරාවන් හා සිත් පහළ වීමේ රටාව පාලනය වන නියාම ධර්මය කුමක්ද?", "චිත්ත නියාමය", "උතු නියාමය", "බීජ නියාමය", "කම්ම නියාමය", "සිතේ ඇතිවන ජවන් හා තදාරම්මණ ආදී ක්‍රියාවලිය චිත්ත නියාමයයි."),
    q("බෝසත් කුමරු මව්කුසින් බිහිවන විට පොළොව කම්පා වීම වැනි ධර්මතා අයත් නියාමය කුමක්ද?", "ධම්ම නියාමය", "උතු නියාමය", "බීජ නියාමය", "චිත්ත නියාමය", "ලෝක ස්වභාවයේ අසිරිමත් ධර්මතා ධම්ම නියාමයට අයත් වේ."),
    q("කුසල් කළ විට යහපත් විපාකත් අකුසල් කළ විට දුක් විපාකත් ලැබීම කුමන නියාමයද?", "කම්ම නියාමය", "උතු නියාමය", "බීජ නියාමය", "ධම්ම නියාමය", "චේතනාන්විත කර්ම අනුව විපාක ලැබීම කම්ම නියාමයයි."),
    q("සමථ භාවනාවෙන් සිත දියුණු කර ලබාගන්නා අසාමාන්‍ය මානසික ශක්තීන් හඳුන්වන්නේ කුමන නමින්ද?", "අභිඥා", "නීවරණ", "ආසව", "සංයෝජන", "ඉද්ධිවිධ, දිබ්බසෝත, පරචිත්ත විජානන ආදී පංච අභිඥා ලෞකික ධ්‍යානවලින් ලැබේ."),
    q("සතර ඍද්ධිපාද ධර්මයන්ට අයත් වන ධර්ම හතර මොනවාද?", "ඡන්ද, විරිය, චිත්ත, වීමංසා", "සද්ධා, සීල, සුත, චාග", "මෙත්තා, කරුණා, මුදිතා, උපේක්ඛා", "සති, සමාධි, පීති, පස්සද්ධි", "දියුණුවට හා විමුක්තියට පදනම් වන බලවත් ගුණ හතර සතර ඍද්ධිපාදයි."),
    q("කාමච්ඡන්දයෙන් තොරව කුසල කර්මයක් කිරීමට ඇති කැමැත්ත හැඳින්වෙන ඍද්ධිපාදය කුමක්ද?", "ඡන්ද ඍද්ධිපාදය", "විරිය ඍද්ධිපාදය", "චිත්ත ඍද්ධිපාදය", "වීමංසා ඍද්ධිපාදය", "යහපත් අරමුණක් ඉටු කර ගැනීමට ඇති කැමැත්ත කුසල ඡන්දයයි."),
    q("භාවනාවේ යෙදෙන කෙනෙකු තුළ නොපසුබට උත්සාහය හා කැපවීම තිබීම කුමන ඍද්ධිපාදයද?", "විරිය ඍද්ධිපාදය", "ඡන්ද ඍද්ධිපාදය", "චිත්ත ඍද්ධිපාදය", "වීමංසා ඍද්ධිපාදය", "අලස බව දුරු කර කුසල් වැඩීම විරිය ඍද්ධිපාදයයි."),
    q("ධර්ම මාර්ගයේදී සිත දැඩිව අරමුණෙහි රඳවා ගැනීම කුමන ඍද්ධිපාදයද?", "චිත්ත ඍද්ධිපාදය", "වීමංසා ඍද්ධිපාදය", "ඡන්ද ඍද්ධිපාදය", "විරිය ඍද්ධිපාදය", "අරමුණෙන් පිට නොයා සිත ස්ථිරව පවත්වා ගැනීමයි."),
    q("විමර්ශන බුද්ධියෙන් යුතුව ධර්මය නුවණින් විමසා බැලීම කුමන ඍද්ධිපාදයද?", "වීමංසා ඍද්ධිපාදය", "ඡන්ද ඍද්ධිපාදය", "විරිය ඍද්ධිපාදය", "චිත්ත ඍද්ධිපාදය", "ප්‍රඥාවෙන් විමසා නිවැරදි මග තහවුරු කර ගැනීම වීමංසාවයි."),
    q("නූපන් අකුසල් නූපදවීම, උපන් අකුසල් ප්‍රහාණය ආදී උත්සාහයන් හතර කුමක්ද?", "සතර සම්‍යක්ප්‍රධාන වීර්යය", "සතර සතිපට්ඨානය", "සතර සංග්‍රහ වස්තු", "සතර අගති", "අකුසල් දුරු කිරීම හා කුසල් වැඩීම සතර සම්මප්පධාන නම් වේ."),
    q("සිතට ඇතුළු වූ සැකය හා පීඩාකාරී සිතුවිලි දුරු කිරීමට 'මරණානුස්සති' භාවනාවෙන් ලැබෙන ප්‍රධාන පලය කුමක්ද?", "ජීවිතයේ අනිත්‍ය බව වැටහී අප්‍රමාදී වීම", "ජීවිතය ගැන බිය වී පලා යාම", "සමාජයට වෛර කිරීම", "කාර්යයන් අතපසු කිරීම", "මරණය ඕනෑම මොහොතක පැමිණිය හැකි බැවින් කුසලයෙහි අප්‍රමාදී වෙයි."),
    q("සුද්ධ සුගති භූමිවලට අයත් වන කාමාවචර දෙව්ලොව ගණන කීයද?", "හයකි", "හතරකි", "දහසයකි", "විස්සකි", "චාතුම්මහාරාජික, තාවතිංස, යාම, තුසිත, නිම්මාණරතී, පරනිම්මිතවසවත්ති දෙව්ලොව 6 කි."),
    q("බෝසතාණන් වහන්සේලා බුද්ධත්වයට පෙර අවසන් දිව්‍ය ආත්මභාවය ගත කරන දෙව්ලොව කුමක්ද?", "තුසිත දෙව්ලොව", "තව්තිසා දෙව්ලොව", "යාම දෙව්ලොව", "බ්‍රහ්ම ලෝකය", "සන්තුසිත දිව්‍යරාජයා ලෙස තුසිත දෙව්ලොව සිට පස්මහ බැලුම් බලා වැඩි සේක."),
    q("බුදු සසුනේ උසස්ම පරිත්‍යාගය හා සිත පිරිසිදු කිරීම සඳහා ප්‍රධාන වන පංච බල ධර්ම මොනවාද?", "සද්ධා, විරිය, සති, සමාධි, පඤ්ඤා", "දාන, සීල, භාවනා, මෛත්‍රී, කරුණා", "ලෝභ, ද්වේෂ, මෝහ, මාන, දිට්ඨි", "රූප, වේදනා, සඤ්ඤා, සංඛාර, විඤ්ඤාණ", "කෙලෙසුන්ගෙන් නොසැලෙන ශක්තීන් පහ පංච බල නම් වේ."),
    q("පංච ඉන්ද්‍රිය හා පංච බල යන දෙකෙහිම පළමු අංගය වන්නේ කුමක්ද?", "සද්ධා", "සති", "පඤ්ඤා", "විරිය", "ශ්‍රද්ධාව සියලු කුසල ධර්මවලට මූලික පදනම සපයයි."),
    q("සෝවාන්, සකදාගාමී, අනාගාමී, අරහත් යන සතර මග සතර ඵලයන්ට පත්වීමේදී ප්‍රහාණය කරන බැමි දහය කුමක්ද?", "දස සංයෝජන ධර්ම", "දස අකුසල්", "දස පාරමිතා", "දස රාජ ධර්ම", "සක්කායදිට්ඨි ආදී සංයෝජන 10 ක්‍රමයෙන් ප්‍රහාණය වීමෙන් රහත් වේ."),
    q("සෝවාන් ඵලයට පත්වීමේදී සම්පූර්ණයෙන්ම ප්‍රහාණය වන සංයෝජන තුන මොනවාද?", "සක්කායදිට්ඨි, විචිකිච්ඡා, සීලබ්බතපරාමාස", "කාමරාග, පටිඝ, මාන", "උද්ධච්ච, අවිජ්ජා, රූපරාග", "ලෝභ, ද්වේෂ, මෝහ", "මුල් සංයෝජන තුන නැති වූ විට සෝවාන් පුද්ගලයා අපාගත නොවේ."),
    q("සකදාගාමී ඵලයට පත් ආර්ය ශ්‍රාවකයාගේ විශේෂ ලක්ෂණය කුමක්ද?", "කාමරාග හා පටිඝ තුනී වී එක්වරක් පමණක් කාම ලෝකයට ඒම", "කෙලෙස් සියල්ල මුලින්ම නැති වීම", "කාමරාග සම්පූර්ණයෙන්ම ප්‍රහාණය වීම", "නැවත ඉපදීමක් නොවීම", "කාමරාග සහ ද්වේෂය (ව්‍යාපාදය) තුනී වීම සකදාගාමී ඵලයේ ස්වභාවයයි."),
    q("අනාගාමී ඵලයට පත් උතුමා මරණින් පසු උපත ලබන්නේ කොහිද?", "ශුද්ධාවාස බ්‍රහ්ම ලෝකයේ", "මිනිස් ලොව", "තව්තිසා දෙව්ලොව", "තිරිසන් ලෝකයේ", "කාමරාග හා පටිඝ ප්‍රහාණය කළ අනාගාමීහු නැවත කාම ලෝකයට නොපැමිණෙති."),
    q("අරහත් ඵලයට පත් වූ උතුමන් තුළ සම්පූර්ණයෙන්ම නැතිවී යන අවසන් සංයෝජන පහ මොනවාද?", "උද්ධම්භාගිය සංයෝජන", "ඕරම්භාගිය සංයෝජන", "පංච නීවරණ", "පංච ශීල", "රූපරාග, අරූපරාග, මාන, උද්ධච්ච, අවිජ්ජා උද්ධම්භාගිය සංයෝජන වේ."),
    q("බෞද්ධ සමාජයේ සිදු කරන 'පුණ්‍යානුමෝදනාව' හෙවත් පින් දීමෙන් මියගිය ඥාතීන්ට පින් අනුමෝදන් විය හැක්කේ කවර තත්ත්වයකදීද?", "පරදත්තූපජීවී ප්‍රේත ආත්මයක සිටී නම්", "නිරයේ සිටී නම්", "බ්‍රහ්ම ලෝකයේ සිටී නම්", "තිරිසන් ආත්මයක සිටී නම්", "තිරෝකුඩ්ඩ සූත්‍රයට අනුව පරදත්තූපජීවී ප්‍රේතයන්ට පින් අනුමෝදන් වී සැප ලැබිය හැකිය."),
    q("මානසික ආතතිය හා කලබලකාරී ස්වභාවය දුරු කර ගැනීමට එදිනෙදා ජීවිතයේදී වඩාත් සුදුසු සරල භාවනාව කුමක්ද?", "ආනාපානසති හා මෛත්‍රී භාවනාව", "තේජෝ කසිණ භාවනාව", "අසුභ භාවනාව පමණක්", "නිරෝධ සමාපත්තිය", "සිහියෙන් හුස්ම දෙස බැලීම හා මෙත් වැඩීම සිත සන්සුන් කරයි."),
    q("කෙනෙකුගේ සිතේ හටගන්නා 'ව්‍යාපාදය' හෙවත් තරහව දුරු කිරීමට ප්‍රතිපක්ෂව වැඩිය යුතු භාවනාව කුමක්ද?", "මෛත්‍රී භාවනාව", "අසුභ භාවනාව", "බුද්ධානුස්සති භාවනාව", "ආකාස කසිණ භාවනාව", "ක්‍රෝධය නැසීමට මෛත්‍රී සිතුවිලි පුරුදු කළ යුතුය."),
    q("රාගය අධික පුද්ගලයෙකුට තම සිත පාලනය කර ගැනීමට සුදුසුම කමටහන කුමක්ද?", "අසුභ භාවනාව", "මෛත්‍රී භාවනාව", "බුද්ධානුස්සති භාවනාව", "මුදිතා භාවනාව", "ශරීරයේ පිළිකුල් ස්වභාවය මෙනෙහි කිරීමෙන් කාම රාගය සංසිඳේ."),
    q("මෝහය හෙවත් මුළාව අධික පුද්ගලයෙකුට සුදුසු භාවනා ක්‍රමය කුමක්ද?", "ආනාපානසති භාවනාව", "ලෝහිත කසිණය", "නීල කසිණය", "අසුභ භාවනාව", "ආනාපානසතිය සිහිය හා නුවණ වර්ධනය කර මෝහය දුරු කරයි."),
    q("සිතේ ඇතිවන අහංකාරකම හෙවත් තමා අනුන් හා සසඳා මැන බැලීමේ කෙලෙස් ස්වභාවය කුමක්ද?", "මානය", "දෘෂ්ටිය", "විචිකිච්ඡාව", "ථීනමිද්ධය", "සෙය්‍ය, සදිස, හීන යන තෙවැදෑරුම් මානය නිවන් මඟ අවුරයි."),
    q("රහත් භාවයට පත් වූ පසුත් පවතින නමුත් කර්ම රැස් නොකරන සිතුවිලි හඳුන්වන්නේ කෙසේද?", "ක්‍රියා සිත්", "විපාක සිත්", "අකුසල සිත්", "කුසල සිත්", "රහතුන්ගේ ක්‍රියා තණ්හාවෙන් තොර බැවින් අලුත් කර්ම බීජ නොසාදයි."),
    q("පටිච්චසමුප්පාදයේ පුරුක් අතර 'විඤ්ඤාණ' හටගැනීමට ප්‍රත්‍ය වන්නේ කුමක්ද?", "සංඛාර", "වේදනා", "තණ්හා", "උපාදාන", "අවිජ්ජා පච්චයා සංඛාරා, සංඛාර පච්චයා විඤ්ඤාණං ලෙස පැවත එයි."),
    q("අභිධර්මයේ ඉගැන්වෙන පරමාර්ථ ධර්ම හතරට අයත් නොවන්නේ කුමක්ද?", "සත්වයා", "චිත්ත", "චෛතසික", "රූප", "චිත්ත, චෛතසික, රූප, නිබ්බාන යනු පරමාර්ථ ධර්ම හතරයි."),
    q("කර්මය හා කර්මඵලය විශ්වාස කිරීම කුමන ආකාරයේ දැක්මක්ද?", "කම්මස්සකතා සම්මා දිට්ඨිය", "මිච්ඡා දිට්ඨිය", "ශාස්වත දිට්ඨිය", "උච්ඡේද දිට්ඨිය", "තම ක්‍රියාවන්හි වගකීම තමා සතු බව පිළිගැනීම කම්මස්සකතා සම්මා දිට්ඨියයි."),
    q("දුක හා සැප දෙකෙහිදීම අකම්පිතව සිටීමේ උතුම් ගුණය බුදුදහමේ හඳුන්වන්නේ කෙසේද?", "තාදී ගුණය", "මාන ගුණය", "විපල්ලාසය", "කුක්කුච්චය", "අටලෝ දහමින් නොසැලෙන මහරහත් උතුමන් තාදී ගුණයෙන් යුක්තය."),
    q("නිවැරදිව භාවනා වැඩීමෙන් පුද්ගලයා තුළ ඇතිවන පරම මානසික සුවය කුමක්ද?", "උපසම හා නිර්වාණ සුවය", "ධන ලාභය", "කීර්තිය පමණක්", "අනුන් යටපත් කිරීම", "සියලු කෙලෙස් සංසිඳීම නිවන් සුවයයි."),
    q("චිත්ත සමාධියෙන් යුතු පුද්ගලයාට ධර්මයේ ඇති සැබෑ තත්ත්වය වැටහෙන බව දැක්වෙන්නේ කුමන පාඨයෙන්ද?", "සමාහිතෝ යථාභූතං පජානාති", "සබ්බේ සංඛාරා අනිච්චා", "අත්තා හි අත්තනෝ නාථෝ", "නහි වේරේන වේරාණි", "සමාධිගත සිත ඇති තැනැත්තා ඇති සැටියෙන් දකී."),
    q("කුසල් සිතක් පහළ වීමේදී ඒ සමඟ නිතරම යෙදෙන ශෝභන චෛතසික ගුණාංගයක් නොවන්නේ කුමක්ද?", "ඊර්ෂ්‍යාව", "අලෝභය", "අදෝසය", "ප්‍රඥාව", "අලෝභ, අදෝස, ප්‍රඥා කුසල චෛතසික වන අතර ඊර්ෂ්‍යාව අකුසල චෛතසිකයකි."),
    q("මානසික ඒකාග්‍රතාව රැක ගැනීමට බාධා කරන 'කුසීතභාවය' දුරු කිරීමට උගන්වන ධර්මය කුමක්ද?", "ආරම්භ ධාතුව (වීර්යය)", "ප්‍රමාදය", "කාමච්ඡන්දය", "විචිකිච්ඡාව", "පටන් ගන්නා වීර්යය හා නොපසුබට උත්සාහය කුසීත බව නසයි."),
    q("සංසාර චක්‍රයේදී මරණයෙන් පසු ඊළඟ භවයේ පළමුව පහළ වන සිත කුමක්ද?", "ප්‍රතිසන්ධි සිත", "චුති සිත", "ජවන් සිත", "ආවර්ජන සිත", "පෙර භවයේ චුති සිතට අනතුරුව නව භවයේ ප්‍රතිසන්ධි සිත පහළ වේ."),
    q("මේ භවයේ අවසන් මොහොතේදී පහළ වන සිත හඳුන්වන අභිධර්ම නාමය කුමක්ද?", "චුති සිත", "ප්‍රතිසන්ධි සිත", "මනෝද්වාරාවජ්ජනය", "සම්පටිච්ඡන සිත", "ජීවිතයේ අවසන් චිත්තක්ෂණය චුති සිත ලෙස හැඳින්වේ."),
    q("වැරදි සිතිවිලි ඇතිවූ විගස එම අරමුණෙන් බැහැරව යහපත් අරමුණකට සිත යොමු කිරීම කුමක්ද?", "අඤ්ඤ නිමිත්ත මනසිකාරය", "නීවරණ වැඩීම", "අයෝනිසෝ මනසිකාරය", "ප්‍රමාද විහරණය", "රාග, ද්වේෂ සිතිවිලි ආ විට අසුභ හෝ මෛත්‍රී අරමුණකට මාරු වීමයි."),
    q("විදර්ශනා ඥාන වැඩීමේදී ශරීරය හා මනස වෙන වෙනම හඳුනාගැනීමේ ඥානය කුමක්ද?", "නාමරූප පරිච්ඡේද ඥානය", "උදයව්‍යය ඥානය", "භංග ඥානය", "සංඛාරුපේක්ඛා ඥානය", "පුද්ගලයෙකු නොව නාම හා රූප පමණක් ඇති බව දකින පළමු විදර්ශනා ඥානයයි."),
    q("කර්ම විපාකයෙන් වැළකී සිටීමට නොහැකි තරමට ප්‍රබල වන බැවින් වහාම කුසල් වැඩිය යුතු බව දක්වන ගාථාව කුමක්ද?", "න අන්තලික්ඛේ න සමුද්දමජ්ඣේ...", "නහි වේරේන වේරාණි...", "මනෝපුබ්බංගමා ධම්මා...", "සබ්බපාපස්ස අකරණං...", "අහසේවත් මුහුදේවත් ගල් ගුහාවකවත් සිට කළ පාප කර්මයෙන් ගැලවිය නොහැකිය.")
  )
}
